import projectData from '../data/projects.json'
import imageData from '../data/images.json'

export type Project = (typeof projectData)[number]

export type ImageSet = {
  width: number
  height: number
  avif: Record<string, string>
  webp: Record<string, string>
  placeholder: string
}

export const projects: Project[] = projectData

/** Generated by `npm run images` from assets/projects/<slug>.* */
const images: Record<string, ImageSet | undefined> = imageData

export const IMAGE_ROOT = '/img/projects/'

export function projectImage(slug: string) {
  return images[slug]
}

export function srcSet(files: Record<string, string>) {
  return Object.entries(files)
    .map(([width, file]) => `${IMAGE_ROOT}${file} ${width}w`)
    .join(', ')
}

const byWidth = (files: Record<string, string>) => Object.keys(files).sort((a, b) => Number(a) - Number(b))

/** URL of the widest rendition in a set. */
export function largestSrc(files: Record<string, string>) {
  return `${IMAGE_ROOT}${files[byWidth(files).at(-1)!]}`
}

/** Smallest and largest WebP, for canvas textures (WebP decodes everywhere). */
export function textureSources(slug: string) {
  const image = images[slug]
  if (!image) return undefined
  const widths = byWidth(image.webp)
  return {
    small: `${IMAGE_ROOT}${image.webp[widths[0]]}`,
    large: `${IMAGE_ROOT}${image.webp[widths.at(-1)!]}`,
  }
}

/** Faces of the 3D box that hold a project; the sixth face is the archive label. */
export const CUBE_SLOTS = 5

/** Featured projects first (in file order), topped up with the rest. */
export const cubeProjects: Project[] = [
  ...projects.filter((project) => project.featured),
  ...projects.filter((project) => !project.featured),
].slice(0, CUBE_SLOTS)

/** "Freelance Project" → "Freelance" */
export function projectType(project: Project) {
  return project.label.replace(/\s+project$/i, '')
}

export const projectTypes = [...new Set(projects.map(projectType))]

/** Deterministic shipping-style tracking number, e.g. VN-2502. */
export function trackingCode(project: Project) {
  const index = projects.indexOf(project) + 1
  return `VN-${project.year.slice(-2)}${String(index).padStart(2, '0')}`
}

/** Typographic stand-in when a project has no screenshot yet. */
export function initials(title: string) {
  const letters = title
    .replace(/[^a-zA-Z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 3)
    .map((word) => word[0]?.toUpperCase())
    .join('')
  return letters || 'WIP'
}
